// One folder per run so concurrent submissions never collide.
const runId = ($json.submittedAt || String(Date.now())).replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/silencedetect-${runId}`;

const binKeys = Object.keys($input.item.binary || {});
if (binKeys.length === 0) {
  throw new Error('No file was uploaded - the Audio File field came through empty.');
}
const binaryKey = binKeys[0];
const upload = $input.item.binary[binaryKey];
const originalName = upload.fileName || 'audio';
const extMatch = originalName.match(/\.([a-zA-Z0-9]+)$/);
const ext = extMatch ? extMatch[1] : 'mp3';

// "-30dB (recommended for narration)" -> -30
const noiseLabel = $json['Silence Threshold'] || '-30dB (recommended for narration)';
const noiseMatch = noiseLabel.match(/-?\d+(\.\d+)?/);
if (!noiseMatch) throw new Error(`Could not read a dB threshold from "${noiseLabel}".`);
const noiseDb = Number(noiseMatch[0]);

const minSilence = Number($json['Minimum Silence Duration (seconds)']) || 0.3;
if (minSilence <= 0) throw new Error(`Minimum Silence Duration must be greater than 0 - got ${minSilence}.`);

const outputLabel = $json['Output'] || 'Report only (JSON, no file)';
const outputMode = outputLabel.startsWith('Report + trimmed') ? 'trim'
  : outputLabel.startsWith('Report + SRT') ? 'srt'
  : 'report_only';

return {
  json: {
    ...$json,
    dir,
    binaryKey,
    inputPath: `${dir}/input.${ext}`,
    noiseDb,
    minSilence,
    outputMode,
  },
  binary: $input.item.binary,
};

// Create the temp folder (Execute Command) wipes json + binary - re-attach both
// from Prepare Run so the uploaded file survives to the write-to-disk step.
const run = $('Prepare Run').item.json;
return { json: run, binary: $('Prepare Run').item.binary };

// FFmpeg prints the total duration near the top of stderr ("Duration: 00:01:23.45")
// and one silence_start/silence_end pair per detected gap - this is the only place
// the real measurements exist.
const cmdResult = $json;
const run = $('Prepare Run').item.json;

// silencedetect always "fails" with a non-zero-ish exit in some ffmpeg builds when
// piping to -f null, so check for the Duration line instead of trusting exitCode alone.
const stderr = cmdResult.stderr || '';

const durMatch = stderr.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/);
if (!durMatch) {
  throw new Error('Could not read audio duration from FFmpeg output: ' + stderr.slice(-500));
}
const totalDuration = Number(durMatch[1]) * 3600 + Number(durMatch[2]) * 60 + Number(durMatch[3]);

const silences = [];
const startRe = /silence_start:\s*(-?\d+(?:\.\d+)?)/g;
const endRe = /silence_end:\s*(-?\d+(?:\.\d+)?)\s*\|\s*silence_duration:\s*(-?\d+(?:\.\d+)?)/g;
const starts = [...stderr.matchAll(startRe)].map(m => Number(m[1]));
const ends = [...stderr.matchAll(endRe)].map(m => ({ end: Number(m[1]), duration: Number(m[2]) }));

for (let i = 0; i < starts.length; i++) {
  const end = ends[i] ? ends[i].end : totalDuration; // trailing silence with no explicit end line = runs to end of file
  const duration = ends[i] ? ends[i].duration : Math.max(0, totalDuration - starts[i]);
  silences.push({ start: Number(starts[i].toFixed(3)), end: Number(end.toFixed(3)), duration: Number(duration.toFixed(3)) });
}

// Speech segments = whatever is NOT silence, within [0, totalDuration].
const speechSegments = [];
let cursor = 0;
for (const s of silences) {
  if (s.start > cursor) {
    speechSegments.push({ start: Number(cursor.toFixed(3)), end: Number(s.start.toFixed(3)), duration: Number((s.start - cursor).toFixed(3)) });
  }
  cursor = Math.max(cursor, s.end);
}
if (cursor < totalDuration) {
  speechSegments.push({ start: Number(cursor.toFixed(3)), end: Number(totalDuration.toFixed(3)), duration: Number((totalDuration - cursor).toFixed(3)) });
}

const totalSilenceSeconds = Number(silences.reduce((a, s) => a + s.duration, 0).toFixed(3));
const totalSpeechSeconds = Number((totalDuration - totalSilenceSeconds).toFixed(3));

return {
  json: {
    outputMode: run.outputMode,
    totalDurationSeconds: Number(totalDuration.toFixed(3)),
    noiseThresholdDb: run.noiseDb,
    minSilenceSeconds: run.minSilence,
    silenceCount: silences.length,
    totalSilenceSeconds,
    totalSpeechSeconds,
    silentPercent: totalDuration > 0 ? Number(((totalSilenceSeconds / totalDuration) * 100).toFixed(1)) : 0,
    silences,
    speechSegments,
  },
};

// Build an FFmpeg filter_complex that cuts every detected speech segment and
// concatenates them back-to-back - the exact segments this same template just
// measured, not a separate guess.
const report = $json;
const run = $('Prepare Run').item.json;
const segments = report.speechSegments;
if (!segments || segments.length === 0) {
  throw new Error('No speech segments were detected - the whole file measured as silence, so there is nothing to trim.');
}

const filters = segments.map((s, i) => `[0:a]atrim=start=${s.start}:end=${s.end},asetpts=PTS-STARTPTS[a${i}]`).join(';');
const concatInputs = segments.map((_s, i) => `[a${i}]`).join('');
const filterComplex = `${filters};${concatInputs}concat=n=${segments.length}:v=0:a=1[out]`;
const trimmedPath = `${run.dir}/trimmed.m4a`;

return {
  json: { ...report, filterComplex, trimmedPath },
};

const cmdResult = $json;
if (cmdResult.exitCode !== undefined && cmdResult.exitCode !== 0) {
  throw new Error('FFmpeg failed to trim the silence: ' + (cmdResult.stderr || '').slice(-500));
}
const report = $('Build the trim filter (FFmpeg)').item.json;
return { json: report };

// Read/Write File's read operation replaces json with file metadata only -
// merge the full silence report back in so the output has both the numbers and the file.
const report = $('Verify the trim succeeded').item.json;
return { json: { ...report, file: $json }, binary: $input.item.binary };

// Build an SRT marker file, one subtitle entry per detected speech segment -
// the same segments this template just measured, turned into a file an editor
// (Premiere, DaVinci, CapCut...) can import directly to jump straight to the
// non-silent parts, instead of only living in a JSON report.
const report = $json;
const run = $('Prepare Run').item.json;
const segments = report.speechSegments;
if (!segments || segments.length === 0) {
  throw new Error('No speech segments were detected - the whole file measured as silence, so there is nothing to mark.');
}

const toSrtTime = (totalSeconds) => {
  const ms = Math.round((totalSeconds % 1) * 1000);
  const wholeSeconds = Math.floor(totalSeconds);
  const h = Math.floor(wholeSeconds / 3600);
  const m = Math.floor((wholeSeconds % 3600) / 60);
  const s = wholeSeconds % 60;
  const pad = (n, len = 2) => String(n).padStart(len, '0');
  return `${pad(h)}:${pad(m)}:${pad(s)},${pad(ms, 3)}`;
};

const srtContent = segments.map((seg, i) => {
  const index = i + 1;
  return `${index}\n${toSrtTime(seg.start)} --> ${toSrtTime(seg.end)}\nSpeech segment ${index} (${seg.duration.toFixed(2)}s)\n`;
}).join('\n');

const srtPath = `${run.dir}/speech-segments.srt`;

return {
  json: { ...report, srtPath },
  binary: { srtFile: { data: Buffer.from(srtContent).toString('base64'), mimeType: 'text/plain', fileName: 'speech-segments.srt' } },
};

// Read/Write File's read operation replaces json with file metadata only -
// merge the full silence report back in so the output has both the numbers and the file.
const report = $('Build SRT markers').item.json;
return { json: { ...report, file: $json }, binary: $input.item.binary };
